<main id="main-content" class="rdc-ctr rdc-artist-page" tabindex="-1"><?php while(have_posts()):the_post();get_template_part('template-parts/ui/content-heading');if(post_password_required()){echo get_the_password_form();continue;} ?><p class="rdc-artist-page__lead">چیدمان گالری با تصاویر موقت رسانه آماده شده است؛ عکس‌های رسمی پس از دریافت جایگزین می‌شوند.</p><div class="rdc-artist-gallery"><?php $images=\RadmanCT\ArtistGallery\images();foreach($images as $id):if(!\RadmanCT\PageTitle\attachment_allowed($id))continue; ?><figure><?php echo wp_get_attachment_image($id,'large',false,array('loading'=>'lazy','sizes'=>'(max-width:600px) 100vw,33vw')); ?></figure><?php endforeach; ?></div><?php endwhile; ?></main><?php get_footer(); ?>
